def is_golomb(marks):
    n = len(marks)
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diff = marks[j] - marks[i]
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

# Test the candidate: 0, 1, 6, 24, 29, 40, 51, 55, 68, 72
candidate = [0, 1, 6, 24, 29, 40, 51, 55, 68, 72]
print(f"Is candidate a Golomb ruler? {is_golomb(candidate)}")
